import React, { useEffect, useState } from "react";

const API_URL = "http://localhost:5000";

function CandidatesPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [showWelcome, setShowWelcome] = useState(false);

  // Fetch candidates
  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await fetch(`${API_URL}/api/candidates`);
        const data = await res.json();
        setCandidates(data);
      } catch (err) {
        console.error("Failed to fetch candidates:", err);
      }
    };
    fetchCandidates();
  }, []);

  // Show welcome when auth becomes available
  useEffect(() => {
    if (auth && auth.username) {
      setShowWelcome(true);
      const timer = setTimeout(() => setShowWelcome(false), 3000); // auto-hide 3s
      return () => clearTimeout(timer);
    }
  }, [auth]); // run whenever auth changes

  return (
    <div style={{ padding: 20 }}>
      {showWelcome && (
        <div
          style={{
            position: "fixed",
            top: 20,
            right: 20,
            backgroundColor: "#4caf50",
            color: "#fff",
            padding: "10px 20px",
            borderRadius: 5,
            boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
            zIndex: 9999,
          }}
        >
          Welcome, {auth.username}!
        </div>
      )}

      <h1>Candidates</h1>
      {candidates.length === 0 && <p>No candidates available.</p>}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
          gap: 20,
        }}
      >
        {candidates.map((c) => (
          <div
            key={c._id}
            style={{
              backgroundColor: "#fff",
              borderRadius: 8,
              padding: 15,
              boxShadow: "0 2px 6px rgba(0,0,0,0.08)",
              textAlign: "center",
            }}
          >
            {c.image ? (
              <img
                src={`${API_URL}/uploads/${c.image}`}
                alt={`${c.firstName} ${c.lastName}`}
                style={{
                  width: "100%",
                  height: 150,
                  objectFit: "cover",
                  borderRadius: 8,
                  marginBottom: 10,
                }}
              />
            ) : (
              <div
                style={{
                  width: "100%",
                  height: 150,
                  backgroundColor: "#ccc",
                  borderRadius: 8,
                  marginBottom: 10,
                }}
              />
            )}
            <h3>{c.firstName} {c.lastName}</h3>
            <p><strong>Candidacy:</strong> {c.candidacy}</p>
            <p><strong>Partylist:</strong> {c.partylist}</p>
            <p><strong>Description:</strong> {c.description || "No description provided"}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default CandidatesPage;
